GROUPS=[{'name':'Prayer names','items':['Fajr','Dhuhr','Asr'],'why':'These are three of the five daily prayers, not the full set.','url':'https://sunnah.com/muslim:612a','source':'Muslim 612a'},
 {'name':'Quran surah titles','items':['Al-Ikhlas','Al-Asr','Al-Kawthar'],'why':'These name surahs 112, 103, and 108.','url':'https://quran.com','source':'Quran surah index'},
 {'name':'Angels named in the Quran','items':['Jibril','Mikal','Malik'],'why':'Jibril and Mikal appear in 2:98; Malik is named in 43:77.','url':'https://quran.com/2/98','source':'Quran 2:98 and 43:77'}]
body='''<div class="playhead"><span class="tag">9 terms · 3 groups</span><span id="status" class="scorebar"></span><button id="reset" class="secondary">Restart puzzle</button></div><p>Select three terms that belong together. Each successful group reveals its label and a source note. Categories are learning aids.</p><div id="tiles" class="tiles"></div><div class="row" style="margin-top:20px"><button id="check">Check three terms</button><button id="clear" class="secondary">Clear selection</button></div><div id="feedback" class="feedback" role="status" aria-live="polite"></div><div id="solved" class="grid"></div>'''
script='const groups='+js(GROUPS)+''';let selected=[],solved=[],attempts=0;const items=groups.flatMap((g,i)=>g.items.map(t=>({t,g:i})));const order=[0,4,6,7,2,3,5,8,1];function render(){$('#tiles').innerHTML=order.map(n=>{const x=items[n];return `<button data-n="${n}" aria-pressed="${selected.includes(n)}" ${solved.includes(x.g)?'disabled class="solved"':''}>${esc(x.t)}</button>`}).join('');$('#status').textContent=`${solved.length} / 3 groups · ${attempts} checks`;$$('[data-n]').forEach(b=>b.onclick=()=>{const n=+b.dataset.n;if(selected.includes(n))selected=selected.filter(x=>x!==n);else if(selected.length<3)selected.push(n);else{$('#feedback').textContent='Three terms are selected. Clear one before choosing another.';return;}render();});$('#check').disabled=solved.length===3;}$('#clear').onclick=()=>{selected=[];render();$('#feedback').textContent='Selection cleared.';};$('#check').onclick=()=>{if(selected.length!==3){$('#feedback').textContent='Select exactly three terms.';return;}attempts++;const g=items[selected[0]].g;if(!selected.every(n=>items[n].g===g)){$('#feedback').textContent='Those terms do not match an intended group. Try another set.';render();return;}solved.push(g);selected=[];const x=groups[g];$('#feedback').textContent=solved.length===3?'All groups found. Use Restart puzzle to try again.':'Group found: '+x.name+'.';$('#solved').insertAdjacentHTML('beforeend',`<article class="card"><h3>${x.name}</h3><p>${x.items.join(' · ')}</p><p>${esc(x.why)}</p><a href="${x.url}" target="_blank" rel="noopener">${x.source}</a>${g===2?' · <a href="https://quran.com/43/77" target="_blank" rel="noopener">43:77</a>':''}</article>`);render();};$('#reset').onclick=()=>{selected=[];solved=[];attempts=0;$('#solved').innerHTML='';$('#feedback').textContent='';render();};render();'''
