body='''<div class="playhead"><span class="tag">3 boards · 9 vocabulary words</span><span id="status" class="scorebar"></span><button id="reset" class="secondary">Restart all boards</button></div><p>Find each word from right to left across one row. Select its letters in order, then choose Check word. Use Tab and Enter, or tap each cell. Clear a selection to start again.</p><p class="muted">Letters use a simplified spelling without vowel marks. They are isolated for the puzzle, not displayed as verse text.</p><div class="split"><div><div id="wordgrid" class="wordgrid" lang="ar" aria-label="Arabic letter grid, right-to-left rows"></div><p id="selection" class="arabic" lang="ar" aria-live="polite"></p><div class="row"><button id="check">Check word</button><button id="clear" class="secondary">Clear selection</button></div></div><aside><h2>Find these words</h2><div id="wordlist"></div><button id="next" hidden>Next board</button></aside></div><div id="feedback" class="feedback" role="status" aria-live="polite"></div>'''
script='const boards='+js(WORDS)+''';let board=0,cells=[],selected=[],found=[],foundCells=[],total=0;const letters=[...'ابتثجحخدذرزسشصضطظعغفقكلمنهوي'];function setup(){selected=[];found=[];foundCells=[];cells=Array.from({length:36},(_,i)=>letters[(i*7+board*3)%letters.length]);boards[board].forEach((w,i)=>[...w[0]].forEach((c,k)=>cells[(i*2)*6+k+1]=c));$('#feedback').textContent='';$('#next').hidden=true;render();}function render(){$('#status').textContent=`Board ${board+1} / 3 · ${found.length} / 3 found · ${total} total`;$('#wordgrid').innerHTML=cells.map((c,i)=>`<button data-i="${i}" class="${selected.includes(i)?'picked ':''}${foundCells.includes(i)?'found':''}" aria-label="Row ${Math.floor(i/6)+1}, column ${i%6+1} from right: ${c}" aria-pressed="${selected.includes(i)}">${c}</button>`).join('');$('#wordlist').innerHTML=boards[board].map((w,i)=>`<p><span lang="ar" class="arabic">${w[0]}</span> · ${w[1]} ${found.includes(i)?'✓ Found':''}<br><a href="https://quran.com/${w[2]}" target="_blank" rel="noopener">Quran ${w[2].replace('/',':')}</a></p>`).join('');$('#selection').textContent=selected.map(i=>cells[i]).join('');$$('[data-i]').forEach(b=>b.onclick=()=>{const n=+b.dataset.i;if(selected.at(-1)===n){selected.pop();render();return;}if(selected.includes(n)){$('#feedback').textContent='Select a new cell or clear the selection.';return;}if(selected.length){const last=selected.at(-1);if(n!==last+1||Math.floor(n/6)!==Math.floor(last/6)){$('#feedback').textContent='Continue one cell to the left in the same row. Column numbers count from the right.';return;}}selected.push(n);render();});$('#check').disabled=found.length===3;}$('#check').onclick=()=>{const word=selected.map(i=>cells[i]).join(''),n=boards[board].findIndex(w=>w[0]===word);if(n<0){$('#feedback').textContent='This selection does not match a target word. Clear it and try again.';return;}if(found.includes(n)){$('#feedback').textContent='You already found that word. Select another target.';return;}found.push(n);total++;foundCells.push(...selected);selected=[];$('#feedback').textContent=found.length===3?(board===2?'All nine vocabulary words found. Restart to play again.':'Board complete. Continue to the next board.'):'Word found. Look for the next target.';$('#next').hidden=found.length!==3||board===2;render();};$('#clear').onclick=()=>{selected=[];$('#feedback').textContent='Selection cleared.';render();};$('#next').onclick=()=>{board++;setup();};$('#reset').onclick=()=>{board=0;total=0;setup();};setup();'''
